import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
test('Starovka : chasse, locaux à louer et pétrole-ferme accessibles dans les deux sens',()=>{
 const ctx=vm.createContext({console,state:{country:'soviet',currentCity:'ville_a'}});
 vm.runInContext(fs.readFileSync(path.join(root,'data.js'),'utf8'),ctx);
 vm.runInContext(fs.readFileSync(path.join(root,'plateau-rue-centrale.js'),'utf8'),ctx);
 const n=vm.runInContext("({caserne:RUE_CENTRALE_NOEUDS.soviet['starovka-rue-bureaux-caserne'],chasse:RUE_CENTRALE_NOEUDS.soviet['starovka-rue-magasin-chasse'],locaux:RUE_CENTRALE_NOEUDS.soviet['starovka-rue-locaux-a-louer'],petrole:RUE_CENTRALE_NOEUDS.soviet['starovka-rue-petrole-ferme'],bas:RC_FLECHE_BAS,haut:RC_FLECHE_HAUT})",ctx);
 assert.equal(n.caserne.liens.toutDroit,'starovka-rue-magasin-chasse');
 assert.equal(n.chasse.liens.arriere,'starovka-rue-bureaux-caserne');
 assert.equal(n.chasse.liens.toutDroit,'starovka-rue-locaux-a-louer');
 assert.equal(n.chasse.flechesStyle.arriere,n.bas);
 assert.match(n.chasse.flechesStyle.toutDroit,/left:43%/);
 assert.match(n.chasse.flechesStyle.toutDroit,/top:10px/);
 assert.equal(n.locaux.liens.arriere,'starovka-rue-magasin-chasse');
 assert.equal(n.locaux.liens.toutDroit,'starovka-rue-petrole-ferme');
 assert.equal(n.locaux.flechesStyle.arriere,n.bas);
 assert.equal(n.locaux.flechesStyle.toutDroit,n.haut);
 assert.equal(n.petrole.liens.arriere,'starovka-rue-locaux-a-louer');
 assert.equal(n.petrole.flechesStyle.arriere,n.bas);
 assert.equal(n.petrole.liens.toutDroit,'starovka-maisons-ferme');
 assert.equal(n.petrole.liens.droite,'starovka-rue-terrains');
 assert.equal(n.petrole.liensEnAttente?.arriere,undefined);
 assert.equal(n.locaux.image,'images/Sovarka/Starovka/Starovka_rue_locaux a louer.webp');
 assert.ok(fs.statSync(path.join(root,n.locaux.image)).size>100);
 assert.ok(fs.statSync(path.join(root,n.chasse.image)).size>100);
 assert.ok(fs.statSync(path.join(root,n.petrole.image)).size>100);
});
test('Starovka : migration du graphe préserve les trois flèches du carrefour',()=>{
 const s=fs.readFileSync(path.join(root,'migrations/20261106053000_starovka_boucle_chasse_locaux_petrole.sql'),'utf8');
 assert.match(s,/"toutDroit":"starovka-rue-locaux-a-louer"/);
 assert.match(s,/"arriere":"starovka-rue-magasin-chasse"/);
 assert.match(s,/"toutDroit":"starovka-rue-petrole-ferme"/);
 assert.match(s,/"arriere":"starovka-rue-locaux-a-louer"/);
 assert.match(s,/"droite":"starovka-rue-terrains"/);
});
